#requires -Version 5.1
# StockFlow: purchase, receipt and sale MVC forms + testable Smart Inventory.
# Requires the Roles and Role Alignment updates. No database records are changed.
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot
if (-not (Test-Path -LiteralPath (Join-Path $root 'TradingManagementSystem.slnx'))) {
    throw 'Put this .ps1 next to TradingManagementSystem.slnx, in the repository root.'
}
$expected = @{
  'TradingManagementSystem.Web/Views/Catalog/Purchases.cshtml' = '1BE58AF31943B49E50EF052BFF0E65E5388C0A37285B6CEE61002D910F47C066'
  'TradingManagementSystem.Web/Views/Catalog/Receipts.cshtml' = '85DFCEF612C87CA420D80D10AB4C0A13C031BA06B9716D664DDA4C9FF90A0A51'
  'TradingManagementSystem.Web/Views/Catalog/Sales.cshtml' = '8A00C7684D8F687F72DF4588463C684667D3B6D3DF7A87139957DB41400C4F33'
  'TradingManagementSystem.Web/Views/Shared/_Layout.cshtml' = '80BE18BC7F5E81E900DD4059F99BC4087C5ACC4E7FBB905D962192F37D78BF31'
  'TradingManagementSystem.Web/Program.cs' = 'D8A874287078194D3C8A7F533D0CF1B7C629C5BB0EE7FE55A81757E1B6469359'
  'TradingManagementSystem.Web/Views/Home/Index.cshtml' = '8C6FCF8B4632E13B7658C12F5D0C88F0301A9D5F6D5924AD3C5902C9CC9356D9'
}
foreach ($rel in $expected.Keys) {
    $full = Join-Path $root ($rel.Replace('/', [IO.Path]::DirectorySeparatorChar))
    if (-not (Test-Path -LiteralPath $full -PathType Leaf)) {
        throw ('Missing required file: ' + $rel + '. Nothing was changed.')
    }
    $actual = (Get-FileHash -Algorithm SHA256 -LiteralPath $full).Hash.ToUpperInvariant()
    if ($actual -ne $expected[$rel]) {
        throw ('Local file was changed or you use an unexpected version: ' + $rel + '. Nothing was changed. Send current project ZIP to get a compatible installer.')
    }
}
$added = @(
  'TradingManagementSystem.Application/Services/SmartInventoryService.cs'
  'TradingManagementSystem.Web/Controllers/CommerceController.cs'
  'TradingManagementSystem.Web/Controllers/SmartInventoryController.cs'
  'TradingManagementSystem.Web/Models/CommerceModels.cs'
  'TradingManagementSystem.Web/Views/Commerce/NewPurchase.cshtml'
  'TradingManagementSystem.Web/Views/Commerce/NewSale.cshtml'
  'TradingManagementSystem.Web/Views/Commerce/RegisterReceipt.cshtml'
  'TradingManagementSystem.Web/Views/SmartInventory/Index.cshtml'
  'TradingManagementSystem.Web/wwwroot/css/stockflow-commerce.css'
)
foreach ($rel in $added) {
    $full = Join-Path $root ($rel.Replace('/', [IO.Path]::DirectorySeparatorChar))
    if (Test-Path -LiteralPath $full) {
        throw ('File already exists and will not be overwritten: ' + $rel + '. Nothing was changed.')
    }
}
