'@
$expectedPayloadHash = 'D95423FF92F8EC0428D5A2B5ECFF5D79D7D2168A64D7731C8892EE5ABBEC6BB8'
$archiveBytes = [Convert]::FromBase64String(($payload -replace '\s',''))
$hashTool = [System.Security.Cryptography.SHA256]::Create()
try { $actualPayloadHash = ([BitConverter]::ToString($hashTool.ComputeHash($archiveBytes))).Replace('-', '') } finally { $hashTool.Dispose() }
if ($actualPayloadHash -ne $expectedPayloadHash) { throw 'Embedded payload checksum mismatch. Nothing changed.' }
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$backupDir = Join-Path $env:TEMP ('StockFlow-Operations-Backup-' + $stamp)
New-Item -ItemType Directory -Path $backupDir -Force | Out-Null
foreach ($rel in $expected.Keys) {
    $target = Join-Path $root ($rel.Replace('/', [IO.Path]::DirectorySeparatorChar))
    $backupTarget = Join-Path $backupDir ($rel.Replace('/', [IO.Path]::DirectorySeparatorChar))
    New-Item -ItemType Directory -Path (Split-Path $backupTarget -Parent) -Force | Out-Null
    Copy-Item -LiteralPath $target -Destination $backupTarget
}
$tmp = Join-Path $env:TEMP ('StockFlow-Operations-Payload-' + $stamp + '.zip')
[IO.File]::WriteAllBytes($tmp, $archiveBytes)
try {
    Expand-Archive -LiteralPath $tmp -DestinationPath $root -Force
} finally {
    Remove-Item -LiteralPath $tmp -ErrorAction SilentlyContinue
}
Write-Host 'StockFlow operations installed: purchase, receipt, sale forms and Smart Inventory.' -ForegroundColor Green
